import React, { useState } from 'react';

const Controls: React.FC<{ onChange: (values: { outer: boolean; onlySuggestions: boolean; success: boolean; warning: boolean }) => void }> = ({ onChange }) => {
    const [outer, setOuter] = useState(false);
    const [onlySuggestions, setOnlySuggestions] = useState(false);
    const [success, setSuccess] = useState(false);
    const [warning, setWarning] = useState(false);

    const handleChange = (setter: React.Dispatch<React.SetStateAction<boolean>>, value: boolean) => {
        setter(value);
        onChange({ outer, onlySuggestions, success, warning });
    };

    return (
        <div>
            <label>
                <input
                    type="checkbox"
                    checked={outer}
                    onChange={(e) => handleChange(setOuter, e.target.checked)}
                />
                Outer?
            </label>
            <label>
                <input
                    type="checkbox"
                    checked={onlySuggestions}
                    onChange={(e) => handleChange(setOnlySuggestions, e.target.checked)}
                />
                OnlySuggestions?
            </label>
            <label>
                <input
                    type="checkbox"
                    checked={success}
                    onChange={(e) => handleChange(setSuccess, e.target.checked)}
                />
                Success?
            </label>
            <label>
                <input
                    type="checkbox"
                    checked={warning}
                    onChange={(e) => handleChange(setWarning, e.target.checked)}
                />
                Warning?
            </label>
        </div>
    );
};

export default Controls;
